-- Manual sales V4. New writes remain disabled until both reader applications are released.
BEGIN;
SET LOCAL ROLE celebix_saas_owner;
CREATE TABLE saas.manual_sales_v4_restore(signature text PRIMARY KEY,definition text NOT NULL,before_hash text NOT NULL,after_hash text);
ALTER TABLE saas.manual_sales_v4_restore ENABLE ROW LEVEL SECURITY;
ALTER TABLE saas.manual_sales_v4_restore FORCE ROW LEVEL SECURITY;
CREATE POLICY manual_sales_v4_restore_owner ON saas.manual_sales_v4_restore TO celebix_saas_owner USING(true) WITH CHECK(true);
REVOKE ALL ON saas.manual_sales_v4_restore FROM PUBLIC,celebix_saas_app,celebix_saas_identity,celebix_saas_workflow,celebix_saas_migrator;
INSERT INTO saas.manual_sales_v4_restore SELECT p.oid::regprocedure::text,pg_get_functiondef(p.oid),md5(pg_get_functiondef(p.oid)),NULL FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='saas' AND p.proname IN('in_store_sales_mutate','in_store_sales_mutate_v2','in_store_sales_mutate_v3','in_store_sales_get','in_store_sales_get_v2','in_store_sales_get_v3','in_store_sales_list','in_store_sales_list_v2','in_store_sales_list_v3','in_store_sales_bootstrap','in_store_sales_bootstrap_v2','in_store_sales_bootstrap_v3','in_store_sales_get_operation','in_store_sales_get_operation_v2','in_store_sales_get_operation_v3','in_store_credit_snapshot_guard','in_store_order_guard','orders_transition_status','orders_update_shipping','accounting_filters_valid','accounting_read','accounting_mutate','accounting_customer_projection');
ALTER TABLE saas.accounting_release_state ADD COLUMN manual_sales_v4_enabled boolean NOT NULL DEFAULT false;
ALTER TABLE saas.in_store_sales DROP CONSTRAINT in_store_v3_contract_version,DROP CONSTRAINT in_store_v3_payment_stage,DROP CONSTRAINT in_store_sales_lifecycle,DROP CONSTRAINT in_store_sales_check1,
 ADD COLUMN sales_channel text NOT NULL DEFAULT 'manual' CHECK(sales_channel IN('manual','social')),
 ADD COLUMN social_platform text CHECK(social_platform IN('instagram','facebook','x','pinterest','tiktok','whatsapp','other')),
 ADD COLUMN social_reference text CHECK(social_reference IS NULL OR length(social_reference) BETWEEN 1 AND 500),
 ADD COLUMN fulfillment_method text NOT NULL DEFAULT 'pickup' CHECK(fulfillment_method IN('pickup','shipping')),
 ADD COLUMN shipping_address jsonb,ADD COLUMN billing_address jsonb,
 ADD COLUMN shipping_cents bigint NOT NULL DEFAULT 0 CHECK(shipping_cents BETWEEN 0 AND 9007199254740991),
 ADD COLUMN payment_parts jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(payment_parts)='array'),
 ADD COLUMN prepare_operation_id uuid,ADD COLUMN payment_plan_version bigint,ADD COLUMN abort_requested boolean NOT NULL DEFAULT false,
 ADD COLUMN accounting_receivable_id uuid,
 ADD CONSTRAINT in_store_v4_contract_version CHECK(contract_version IN(1,2,3,4)),
 ADD CONSTRAINT in_store_v4_total CHECK(total_cents=subtotal_cents-discount_cents+shipping_cents AND total_cents BETWEEN 0 AND 9007199254740991),
 ADD CONSTRAINT in_store_v4_payment_stage CHECK(contract_version IN(1,4) OR status NOT IN('payment_pending','payment_received','completed') OR payment_method IS NOT NULL OR contract_version=3 AND initial_collection_cents=0),
 ADD CONSTRAINT in_store_sales_lifecycle CHECK((status IN('draft','held','payment_pending','cancelled') AND payment_received_at IS NULL AND completed_at IS NULL AND order_id IS NULL AND order_number IS NULL) OR(status='payment_received' AND payment_received_at IS NOT NULL AND completed_at IS NULL AND order_id IS NULL AND order_number IS NULL) OR(status='completed' AND (payment_received_at IS NOT NULL OR contract_version IN(3,4) AND initial_collection_cents=0) AND completed_at IS NOT NULL AND order_number IS NOT NULL)),
 ADD CONSTRAINT in_store_v4_receivable FOREIGN KEY(store_id,accounting_receivable_id) REFERENCES saas.accounting_receivables(store_id,id);
CREATE TABLE saas.in_store_payment_receipts_v4(
 id uuid PRIMARY KEY,store_id uuid NOT NULL,sale_id uuid NOT NULL,part_id uuid NOT NULL,prepare_operation_id uuid NOT NULL,
 operation_id uuid NOT NULL UNIQUE,actor_membership_id uuid NOT NULL,amount_cents bigint NOT NULL CHECK(amount_cents BETWEEN 1 AND 9007199254740991),payment_method text NOT NULL CHECK(payment_method IN('cash','card','bank_transfer')),slip_reference text,
 received_at timestamptz NOT NULL,event_id uuid NOT NULL UNIQUE,account_id uuid NOT NULL,
 UNIQUE(store_id,id),UNIQUE(store_id,sale_id,part_id),FOREIGN KEY(store_id,sale_id) REFERENCES saas.in_store_sales(store_id,id),FOREIGN KEY(store_id,actor_membership_id) REFERENCES saas.memberships(store_id,id),FOREIGN KEY(store_id,event_id) REFERENCES saas.accounting_events(store_id,id),FOREIGN KEY(store_id,account_id) REFERENCES saas.accounting_accounts(store_id,id));
CREATE TABLE saas.in_store_payment_returns_v4(
 receipt_id uuid PRIMARY KEY,store_id uuid NOT NULL,event_id uuid NOT NULL UNIQUE,operation_id uuid NOT NULL UNIQUE,actor_membership_id uuid NOT NULL,returned_at timestamptz NOT NULL,reason text NOT NULL CHECK(length(reason) BETWEEN 1 AND 2000),
 FOREIGN KEY(store_id,receipt_id) REFERENCES saas.in_store_payment_receipts_v4(store_id,id),FOREIGN KEY(store_id,event_id) REFERENCES saas.accounting_events(store_id,id),FOREIGN KEY(store_id,actor_membership_id) REFERENCES saas.memberships(store_id,id));
CREATE TABLE saas.in_store_obsolete_payment_reconciliations_v4(operation_id uuid PRIMARY KEY,store_id uuid NOT NULL,sale_id uuid NOT NULL,original_operation_id uuid NOT NULL UNIQUE,prepare_operation_id uuid NOT NULL,part_id uuid NOT NULL,amount_cents bigint NOT NULL CHECK(amount_cents>0),payment_method text NOT NULL CHECK(payment_method IN('cash','card','bank_transfer')),actor_membership_id uuid NOT NULL,reconciled_at timestamptz NOT NULL,reason text NOT NULL CHECK(reason='physical_return_confirmed'),FOREIGN KEY(store_id,sale_id) REFERENCES saas.in_store_sales(store_id,id),FOREIGN KEY(store_id,actor_membership_id) REFERENCES saas.memberships(store_id,id));
DO $tables$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['in_store_payment_receipts_v4','in_store_payment_returns_v4','in_store_obsolete_payment_reconciliations_v4'] LOOP EXECUTE format('ALTER TABLE saas.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE saas.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY manual_sales_v4_owner ON saas.%I TO celebix_saas_owner USING(true) WITH CHECK(true)',t);EXECUTE format('REVOKE ALL ON saas.%I FROM PUBLIC,celebix_saas_app,celebix_saas_identity,celebix_saas_workflow,celebix_saas_migrator',t);EXECUTE format('CREATE TRIGGER manual_sales_v4_immutable BEFORE UPDATE OR DELETE ON saas.%I FOR EACH ROW EXECUTE FUNCTION saas.accounting_immutable()',t);END LOOP;END $tables$;
CREATE FUNCTION saas.in_store_payment_parts_valid_v4(p_parts jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,saas AS $f$
DECLARE part jsonb;BEGIN
 IF p_parts IS NULL OR jsonb_typeof(p_parts)<>'array' OR jsonb_array_length(p_parts)>100 THEN RETURN false;END IF;
 FOR part IN SELECT value FROM jsonb_array_elements(p_parts) LOOP
 IF jsonb_typeof(part)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(part))<>3 OR NOT(part?&ARRAY['partId','paymentMethod','amountCents']) OR jsonb_typeof(part->'partId')<>'string' OR part->>'partId'!~'^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$' OR jsonb_typeof(part->'paymentMethod')<>'string' OR part->>'paymentMethod' NOT IN('cash','card','bank_transfer') OR jsonb_typeof(part->'amountCents')<>'number' OR (part->>'amountCents')::numeric<>trunc((part->>'amountCents')::numeric) OR (part->>'amountCents')::numeric NOT BETWEEN 1 AND 9007199254740991 THEN RETURN false;END IF;
 END LOOP;
 RETURN jsonb_array_length(p_parts)=(SELECT count(DISTINCT value->>'partId') FROM jsonb_array_elements(p_parts)) AND coalesce((SELECT sum((value->>'amountCents')::numeric) FROM jsonb_array_elements(p_parts)),0)<=9007199254740991;
 EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END $f$;
CREATE FUNCTION saas.in_store_address_valid_v4(p_address jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,saas AS $f$
DECLARE k text;v jsonb;BEGIN IF p_address IS NULL OR jsonb_typeof(p_address)<>'object' OR NOT(p_address?&ARRAY['recipientName','line1','city','country']) THEN RETURN false;END IF;
 FOR k,v IN SELECT key,value FROM jsonb_each(p_address) LOOP IF k NOT IN('recipientName','line1','line2','district','city','postalCode','country') OR jsonb_typeof(v)<>'string' OR length(v#>>'{}') NOT BETWEEN 1 AND (CASE WHEN k IN('line1','line2') THEN 300 WHEN k='postalCode' THEN 32 WHEN k='country' THEN 2 ELSE 200 END) OR v#>>'{}'<>btrim(v#>>'{}') OR v#>>'{}'~'[[:cntrl:]]' THEN RETURN false;END IF;END LOOP;RETURN p_address->>'country'~'^[A-Z]{2}$';END $f$;
CREATE FUNCTION saas.in_store_quote_v4(p_store uuid,p_member uuid,p_now timestamptz,p_intent jsonb,p_existing jsonb DEFAULT '[]') RETURNS TABLE(outcome text,result_payload jsonb) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,saas AS $f$
DECLARE r record;selected saas.customers%ROWTYPE;snapshot jsonb;initial bigint;shipping bigint;due date;base jsonb;method text;parts jsonb;old_total bigint;new_total bigint;BEGIN
 IF p_intent IS NULL OR jsonb_typeof(p_intent)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(p_intent))<>15 OR NOT(p_intent?&ARRAY['locationId','items','discount','customerName','note','customerId','dueDate','paymentParts','salesChannel','socialPlatform','socialReference','fulfillmentMethod','shippingAddress','billingAddress','shippingCents']) OR pg_column_size(p_intent)>65536 OR NOT saas.in_store_payment_parts_valid_v4(p_intent->'paymentParts') THEN RETURN QUERY SELECT 'invalid_input',NULL::jsonb;RETURN;END IF;
 IF p_intent->>'salesChannel' IS NULL OR p_intent->>'fulfillmentMethod' IS NULL OR p_intent->>'salesChannel' NOT IN('manual','social') OR p_intent->>'fulfillmentMethod' NOT IN('pickup','shipping') OR p_intent->>'salesChannel'='manual' AND (p_intent->>'socialPlatform' IS NOT NULL OR p_intent->>'socialReference' IS NOT NULL) OR p_intent->>'salesChannel'='social' AND (p_intent->>'socialPlatform' IS NULL OR p_intent->>'socialPlatform' NOT IN('instagram','facebook','x','pinterest','tiktok','whatsapp','other')) OR p_intent->>'socialReference' IS NOT NULL AND (jsonb_typeof(p_intent->'socialReference')<>'string' OR length(p_intent->>'socialReference') NOT BETWEEN 1 AND 500 OR p_intent->>'socialReference'<>btrim(p_intent->>'socialReference') OR p_intent->>'socialReference'~'[[:cntrl:]]') THEN RETURN QUERY SELECT 'invalid_input',NULL::jsonb;RETURN;END IF;
 IF p_intent->>'shippingCents' IS NULL OR jsonb_typeof(p_intent->'shippingCents')<>'number' OR (p_intent->>'shippingCents')::numeric<>trunc((p_intent->>'shippingCents')::numeric) OR (p_intent->>'shippingCents')::numeric NOT BETWEEN 0 AND 9007199254740991 THEN RETURN QUERY SELECT 'invalid_input',NULL::jsonb;RETURN;END IF;shipping:=(p_intent->>'shippingCents')::bigint;
 IF p_intent->>'fulfillmentMethod'='pickup' AND (shipping<>0 OR p_intent->>'shippingAddress' IS NOT NULL OR p_intent->>'billingAddress' IS NOT NULL) OR p_intent->>'fulfillmentMethod'='shipping' AND (NOT saas.in_store_address_valid_v4(p_intent->'shippingAddress') OR p_intent->>'billingAddress' IS NOT NULL AND NOT saas.in_store_address_valid_v4(p_intent->'billingAddress')) THEN RETURN QUERY SELECT 'invalid_input',NULL::jsonb;RETURN;END IF;
 IF p_intent->>'customerId' IS NOT NULL THEN IF jsonb_typeof(p_intent->'customerId')<>'string' OR p_intent->>'customerId'!~'^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$' THEN RETURN QUERY SELECT 'invalid_input',NULL::jsonb;RETURN;END IF;SELECT * INTO selected FROM saas.customers WHERE store_id=p_store AND id=(p_intent->>'customerId')::uuid;IF NOT FOUND THEN RETURN QUERY SELECT 'not_found',NULL::jsonb;RETURN;END IF;IF selected.status<>'active' OR selected.archived_at IS NOT NULL THEN RETURN QUERY SELECT 'customer_archived',NULL::jsonb;RETURN;END IF;snapshot:=saas.in_store_pos_customer_projection(selected);END IF;
 IF p_intent->>'customerName' IS NOT NULL AND (jsonb_typeof(p_intent->'customerName')<>'string' OR length(p_intent->>'customerName') NOT BETWEEN 1 AND (CASE WHEN p_intent->>'customerId' IS NULL THEN 200 ELSE 201 END) OR p_intent->>'customerName'<>btrim(p_intent->>'customerName') OR p_intent->>'customerName'~'[[:cntrl:]]') THEN RETURN QUERY SELECT 'invalid_input',NULL::jsonb;RETURN;END IF;
 IF p_intent->>'dueDate' IS NOT NULL THEN IF p_intent->>'dueDate'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RETURN QUERY SELECT 'invalid_input',NULL::jsonb;RETURN;END IF;due:=(p_intent->>'dueDate')::date;IF due::text<>p_intent->>'dueDate' THEN RETURN QUERY SELECT 'invalid_input',NULL::jsonb;RETURN;END IF;END IF;
 SELECT CASE WHEN count(DISTINCT value->>'paymentMethod')=1 THEN min(value->>'paymentMethod') ELSE NULL END,coalesce(sum((value->>'amountCents')::bigint),0) INTO method,initial FROM jsonb_array_elements(p_intent->'paymentParts');
 base:=jsonb_build_object('locationId',p_intent->'locationId','items',p_intent->'items','discount',p_intent->'discount','customerName',CASE WHEN snapshot IS NULL THEN p_intent->'customerName' ELSE 'null'::jsonb END,'note',p_intent->'note','paymentMethod',CASE WHEN method='bank_transfer' THEN 'cash' ELSE method END);
 SELECT * INTO r FROM saas.in_store_quote_v2(p_store,p_member,p_now,base,p_existing);IF r.outcome<>'found' THEN RETURN QUERY SELECT r.outcome::text,NULL::jsonb;RETURN;END IF;
 IF (r.result_payload->>'totalCents')::numeric+shipping>9007199254740991 THEN RETURN QUERY SELECT 'invalid_input',NULL::jsonb;RETURN;END IF;
 new_total:=(r.result_payload->>'totalCents')::bigint+shipping;parts:=p_intent->'paymentParts';
 SELECT coalesce(sum((value->>'lineNetCents')::bigint),0)+shipping INTO old_total FROM jsonb_array_elements(p_existing);
 IF new_total>0 AND jsonb_array_length(p_existing)>0 AND jsonb_array_length(parts)=1 AND initial=old_total AND new_total<>old_total THEN parts:=jsonb_set(parts,'{0,amountCents}',to_jsonb(new_total));initial:=new_total;
 ELSIF initial>new_total AND jsonb_array_length(p_existing)>0 AND p_existing IS DISTINCT FROM r.result_payload->'items' THEN parts:='[]';initial:=0;method:=NULL;
 ELSIF initial>new_total THEN RETURN QUERY SELECT 'invalid_input',NULL::jsonb;RETURN;END IF;
 RETURN QUERY SELECT 'found',r.result_payload||jsonb_build_object('totalCents',(r.result_payload->>'totalCents')::bigint+shipping,'shippingCents',shipping,'paymentParts',parts,'customer',snapshot,'initialCollectionCents',initial,'paymentMethod',method,'dueDate',due);
 EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR datetime_field_overflow THEN RETURN QUERY SELECT 'invalid_input',NULL::jsonb;
END $f$;
CREATE FUNCTION saas.in_store_projection_v4_value(p_sale jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,saas AS $f$
 SELECT CASE WHEN p_sale IS NULL THEN NULL ELSE saas.in_store_projection_v3_value(p_sale)||jsonb_build_object('salesChannel',coalesce(p_sale->'salesChannel','"manual"'),'socialPlatform',p_sale->'socialPlatform','socialReference',p_sale->'socialReference','fulfillmentMethod',coalesce(p_sale->'fulfillmentMethod','"pickup"'),'shippingAddress',p_sale->'shippingAddress','billingAddress',p_sale->'billingAddress','shippingCents',coalesce(p_sale->'shippingCents','0'),'paymentParts',coalesce(p_sale->'paymentParts','[]'),'prepareOperationId',p_sale->'prepareOperationId','abortRequested',coalesce(p_sale->'abortRequested','false'),'totals',(p_sale->'totals')||jsonb_build_object('shippingCents',coalesce(p_sale->'shippingCents','0'))) END
$f$;
CREATE FUNCTION saas.in_store_sales_projection_v4(p_store uuid,p_sale uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,saas AS $f$
 SELECT saas.in_store_projection_v4_value(saas.in_store_sales_projection_v3(p_store,p_sale)||jsonb_build_object('salesChannel',s.sales_channel,'socialPlatform',s.social_platform,'socialReference',s.social_reference,'fulfillmentMethod',s.fulfillment_method,'shippingAddress',s.shipping_address,'billingAddress',s.billing_address,'shippingCents',s.shipping_cents,'prepareOperationId',s.prepare_operation_id,'abortRequested',s.abort_requested,'finance',CASE WHEN s.status='completed' THEN saas.accounting_order_finance(p_store,s.order_id) ELSE NULL END,'paymentParts',coalesce((SELECT jsonb_agg(part||jsonb_build_object('receiptId',receipt.id,'receivedAt',saas.orders_json_timestamp(receipt.received_at),'actorMembershipId',receipt.actor_membership_id,'refundEventId',returned.event_id,'returnedAt',saas.orders_json_timestamp(returned.returned_at)) ORDER BY ordinal) FROM jsonb_array_elements(s.payment_parts) WITH ORDINALITY plan(part,ordinal) LEFT JOIN saas.in_store_payment_receipts_v4 receipt ON receipt.store_id=s.store_id AND receipt.sale_id=s.id AND receipt.part_id=(part->>'partId')::uuid LEFT JOIN saas.in_store_payment_returns_v4 returned ON returned.store_id=receipt.store_id AND returned.receipt_id=receipt.id),'[]'))) FROM saas.in_store_sales s WHERE s.store_id=p_store AND s.id=p_sale
$f$;
CREATE FUNCTION saas.accounting_post_pos_sale_v4(p_store uuid,p_sale uuid,p_order uuid,p_operation uuid,p_actor uuid,p_now timestamptz) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,saas AS $f$
DECLARE sale saas.in_store_sales%ROWTYPE;receivable uuid;event uuid;receipt record;BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('saas.accounting.store:'||p_store::text,0));SELECT * INTO STRICT sale FROM saas.in_store_sales WHERE store_id=p_store AND id=p_sale;
 IF sale.contract_version<>4 OR sale.abort_requested OR NOT EXISTS(SELECT 1 FROM saas.orders WHERE store_id=p_store AND id=p_order AND source='in_store' AND total_cents=sale.total_cents) THEN RAISE EXCEPTION 'ACCOUNTING_POS_V4_INVALID';END IF;
 receivable:=saas.inventory_deterministic_uuid('accounting','saas.accounting.receivable:'||p_store::text||':'||p_order::text);event:=saas.inventory_deterministic_uuid('accounting','saas.accounting.sale:'||p_operation::text);
 INSERT INTO saas.accounting_receivables(id,store_id,customer_id,customer_snapshot,order_id,channel,currency,sale_cents,collected_cents,occurred_at,due_date) VALUES(receivable,p_store,sale.customer_id,coalesce(sale.customer_snapshot,'{}'),p_order,'POS','TRY',sale.total_cents,sale.initial_collection_cents,p_now,sale.due_date);
 INSERT INTO saas.accounting_events(id,store_id,operation_id,kind,currency,amount_cents,customer_id,order_id,channel,actor_membership_id,occurred_at,created_at,metadata) VALUES(event,p_store,p_operation,'sale','TRY',sale.total_cents,sale.customer_id,p_order,'POS',p_actor,p_now,p_now,jsonb_build_object('saleId',p_sale,'salesChannel',sale.sales_channel));
 FOR receipt IN SELECT r.* FROM saas.in_store_payment_receipts_v4 r WHERE r.store_id=p_store AND r.sale_id=p_sale LOOP INSERT INTO saas.accounting_allocations VALUES(p_store,receipt.event_id,receivable,'collect',receipt.amount_cents);END LOOP;
 UPDATE saas.in_store_sales SET accounting_receivable_id=receivable WHERE store_id=p_store AND id=p_sale;
 PERFORM saas.accounting_bump_customer(p_store,sale.customer_id,'TRY');PERFORM saas.accounting_sync_order(p_store,p_order,p_now);RETURN saas.accounting_order_finance(p_store,p_order);
END $f$;

-- Clone the CURRENT V3 body (including platform support and discard217), then apply exact reviewed anchors.
DO $v4$ DECLARE definition text;before text;BEGIN
 definition:=pg_get_functiondef('saas.in_store_sales_mutate_v3(uuid,uuid,uuid,uuid,text,bigint,timestamptz,uuid,text,uuid,bigint,text,jsonb)'::regprocedure);
 definition:=replace(replace(replace(definition,'in_store_sales_mutate_v3','in_store_sales_mutate_v4'),'in_store_sales_projection_v3','in_store_sales_projection_v4'),'in_store_quote_v3','in_store_quote_v4');
 before:=definition;definition:=replace(definition,$old$'confirm_payment','complete'$old$,$new$'confirm_payment','complete','revise_payments','abort','return_payment','reconcile_payment'$new$);IF before=definition THEN RAISE EXCEPTION 'MANUAL_V4_ANCHOR_MISSING: %','''confirm_payment'',''complete'',''cancel'',''takeover''';END IF;
 before:=definition;definition:=replace(definition,$old$position integer:=0; selected_location uuid;$old$,$new$position integer:=0; selected_location uuid; part jsonb; receipt_v4 saas.in_store_payment_receipts_v4%ROWTYPE; customer_v4 saas.customers%ROWTYPE; account_v4 uuid; event_v4 uuid; receipt_id_v4 uuid; initial_v4 bigint; method_v4 text; parts_v4 jsonb; due_v4 date; original_prepare_v4 jsonb;original_part_v4 jsonb;$new$);IF before=definition THEN RAISE EXCEPTION 'MANUAL_V4_ANCHOR_MISSING: %','position integer:=0; selected_location uuid;';END IF;
 before:=definition;definition:=replace(definition,$old$  IF p_expected_version$old$,$new$  IF NOT (SELECT manual_sales_v4_enabled FROM saas.accounting_release_state WHERE singleton) THEN RETURN QUERY SELECT 'feature_not_enabled',NULL::jsonb;RETURN;END IF;
  IF p_expected_version$new$);IF before=definition THEN RAISE EXCEPTION 'MANUAL_V4_ANCHOR_MISSING: %',' IF p_kind=''create'' THEN
  IF p_expected_version';END IF;
 before:=definition;definition:=replace(definition,$old$IF selected.version<>p_expected_version OR p_now<selected.updated_at THEN$old$,$new$IF (selected.version<>p_expected_version AND NOT(p_expected_version<=selected.version AND (p_kind='return_payment' AND selected.abort_requested OR p_kind='reconcile_payment' OR p_kind='confirm_payment' AND selected.prepare_operation_id=(p_args->>'prepareOperationId')::uuid AND EXISTS(SELECT 1 FROM saas.in_store_operations history CROSS JOIN LATERAL jsonb_array_elements(history.result_payload#>'{sale,paymentParts}') old_part JOIN LATERAL jsonb_array_elements(selected.payment_parts) current_part ON current_part->>'partId'=old_part->>'partId' AND current_part->>'paymentMethod'=old_part->>'paymentMethod' AND current_part->>'amountCents'=old_part->>'amountCents' WHERE history.store_id=p_store_id AND history.sale_id=p_sale_id AND (history.result_payload#>>'{sale,version}')::bigint=p_expected_version AND history.result_payload#>>'{sale,prepareOperationId}'=p_args->>'prepareOperationId' AND old_part->>'partId'=p_args->>'partId')))) OR p_now<selected.updated_at THEN$new$);IF before=definition THEN RAISE EXCEPTION 'MANUAL_V4_ANCHOR_MISSING: %','IF selected.version<>p_expected_version OR p_now<selected.updated';END IF;
 before:=definition;definition:=replace(definition,$old$IF selected.contract_version<3 AND p_kind<>'update' THEN$old$,$new$IF selected.contract_version<>4 AND p_kind<>'update' THEN$new$);IF before=definition THEN RAISE EXCEPTION 'MANUAL_V4_ANCHOR_MISSING: %','IF selected.contract_version<3 AND p_kind<>''update'' THEN';END IF;
 before:=definition;definition:=replace(definition,$old$  intent_payload:=CASE WHEN p_kind='update'$old$,$new$  IF selected.contract_version<>4 AND p_kind='update' AND NOT (SELECT manual_sales_v4_enabled FROM saas.accounting_release_state WHERE singleton) THEN RETURN QUERY SELECT 'feature_not_enabled',NULL::jsonb;RETURN;END IF;
  intent_payload:=CASE WHEN p_kind='update'$new$);IF before=definition THEN RAISE EXCEPTION 'MANUAL_V4_ANCHOR_MISSING: %','  intent_payload:=CASE WHEN p_kind=''update''';END IF;
