-- Additive V4 ABI; legacy operation snapshots are never rewritten.
DO $facades$ DECLARE fn record;definition text;BEGIN
 FOR fn IN SELECT p.oid,p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='saas' AND p.proname IN('in_store_sales_create_v3','in_store_sales_update_v3','in_store_sales_hold_v3','in_store_sales_prepare_v3','in_store_sales_complete_v3','in_store_sales_cancel_v3','in_store_sales_discard_v3','in_store_sales_takeover_v3','in_store_sales_get_v3','in_store_sales_get_operation_v3','in_store_sales_list_v3','in_store_sales_bootstrap_v3','in_store_sales_list_staff_v3','in_store_sales_recover_staff_v3','in_store_sales_set_staff_v3') LOOP
  definition:=pg_get_functiondef(fn.oid);
  definition:=replace(replace(replace(replace(definition,'in_store_sales_mutate_v3','in_store_sales_mutate_v4'),'in_store_sales_projection_v3','in_store_sales_projection_v4'),'in_store_projection_v3_value','in_store_projection_v4_value'),'_v3','_v4');
  -- The staff projection itself is shared; only its versioned read facade is new.
  definition:=replace(definition,'in_store_staff_projection_v4','in_store_staff_projection_v3');
  IF fn.proname='in_store_sales_bootstrap_v3' THEN definition:=replace(definition,'sum(subtotal_cents)','sum(subtotal_cents+shipping_cents)');definition:=replace(definition,$old$'creditSalesAvailable',saas.accounting_credit_enabled()$old$,$new$'creditSalesAvailable',saas.accounting_credit_enabled(),'manualSalesV4Available',(SELECT manual_sales_v4_enabled FROM saas.accounting_release_state WHERE singleton)$new$);END IF;
  EXECUTE definition;
 END LOOP;
END $facades$;
