-- Freeze V4 price/delivery/channel while allowing only the checked pending-part revision.
DO $guard$ DECLARE definition text;BEGIN
 definition:=pg_get_functiondef('saas.in_store_credit_snapshot_guard()'::regprocedure);
 definition:=replace(definition,'OLD.contract_version=3','OLD.contract_version IN(3,4)');
 definition:=replace(definition,$old$BEGIN$old$,$new$BEGIN
 IF OLD.contract_version=4 AND OLD.status IN('payment_pending','payment_received','completed') THEN
  IF (OLD.sales_channel,OLD.social_platform,OLD.social_reference,OLD.fulfillment_method,OLD.shipping_address,OLD.billing_address,OLD.shipping_cents,OLD.prepare_operation_id) IS DISTINCT FROM (NEW.sales_channel,NEW.social_platform,NEW.social_reference,NEW.fulfillment_method,NEW.shipping_address,NEW.billing_address,NEW.shipping_cents,NEW.prepare_operation_id) AND NEW.status<>'draft' THEN RAISE EXCEPTION 'IN_STORE_V4_SNAPSHOT_IMMUTABLE';END IF;
  IF current_setting('saas.in_store.v4_revision',true)=OLD.store_id::text||':'||OLD.id::text AND OLD.status IN('payment_pending','payment_received') AND NOT OLD.abort_requested AND OLD.items=NEW.items AND OLD.total_cents=NEW.total_cents AND OLD.intent-ARRAY['paymentParts','customerId','dueDate']=NEW.intent-ARRAY['paymentParts','customerId','dueDate'] THEN RETURN NEW;END IF;
  IF OLD.payment_parts IS DISTINCT FROM NEW.payment_parts THEN RAISE EXCEPTION 'IN_STORE_V4_PARTS_IMMUTABLE';END IF;
 END IF;
$new$);
 EXECUTE definition;
END $guard$;
