  definition:=pg_get_functiondef(fn.oid);anchor:=' IF prior.sale_id IS NULL';
  IF position(anchor IN definition)=0 THEN RAISE EXCEPTION 'MANUAL_V4_LEGACY_OPERATION_ANCHOR: %',fn.proname;END IF;
