 -- Open balance totals are filtered by the same receivable dimension.
 definition:=replace(definition,$old$FROM saas.accounting_receivables WHERE store_id=p_store AND (NOT(p_filters?'currency')$old$,$new$FROM saas.accounting_receivables WHERE store_id=p_store AND saas.accounting_sales_channel_matches_v4(p_store,id,order_id,NULL,p_filters->>'salesChannel') AND (NOT(p_filters?'currency')$new$);
 definition:=replace(definition,$old$AND currency=code.currency AND$old$,$new$AND currency=code.currency AND saas.accounting_sales_channel_matches_v4(p_store,id,order_id,NULL,p_filters->>'salesChannel') AND$new$);
 EXECUTE definition;
 -- Customer history follows final allocations when a pending receipt was originally anonymous.
 definition:=pg_get_functiondef('saas.accounting_customer_projection(uuid,uuid,text)'::regprocedure);
 definition:=replace(definition,$old$FROM saas.accounting_events WHERE store_id=p_store AND customer_id=p_customer AND currency=p_currency$old$,$new$FROM saas.accounting_events WHERE store_id=p_store AND (customer_id=p_customer OR EXISTS(SELECT 1 FROM saas.accounting_allocations a JOIN saas.accounting_receivables r ON r.store_id=a.store_id AND r.id=a.receivable_id WHERE a.store_id=p_store AND a.event_id=accounting_events.id AND r.customer_id=p_customer)) AND currency=p_currency$new$);EXECUTE definition;
END $accounting$;
-- Projection context is read-only; the immutable ledger metadata remains intact.
CREATE FUNCTION saas.accounting_manual_event_context_v4(p_store uuid,p_event uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,saas AS $f$
 SELECT jsonb_build_object('saleStatus',s.status,'pendingSale',s.status<>'completed') FROM saas.in_store_payment_receipts_v4 r JOIN saas.in_store_sales s ON s.store_id=r.store_id AND s.id=r.sale_id LEFT JOIN saas.in_store_payment_returns_v4 returned ON returned.store_id=r.store_id AND returned.receipt_id=r.id WHERE r.store_id=p_store AND (r.event_id=p_event OR returned.event_id=p_event)
$f$;
DO $projection$ DECLARE definition text;BEGIN
 INSERT INTO saas.manual_sales_v4_restore SELECT 'saas.accounting_event_projection(uuid,uuid)',pg_get_functiondef('saas.accounting_event_projection(uuid,uuid)'::regprocedure),md5(pg_get_functiondef('saas.accounting_event_projection(uuid,uuid)'::regprocedure)),NULL;
 definition:=pg_get_functiondef('saas.accounting_event_projection(uuid,uuid)'::regprocedure);
 definition:=replace(definition,$old$'metadata',e.metadata$old$,$new$'metadata',e.metadata||coalesce(saas.accounting_manual_event_context_v4(p_store,e.id),'{}')$new$);EXECUTE definition;
END $projection$;
-- Seal internals, and grant only the versioned domain RPC entrypoints.
DO $seal$ DECLARE fn record;BEGIN
 FOR fn IN SELECT p.oid,p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='saas' AND p.proname=ANY(ARRAY['in_store_payment_parts_valid_v4','in_store_address_valid_v4','in_store_quote_v4','in_store_projection_v4_value','in_store_sales_projection_v4','accounting_post_pos_sale_v4','in_store_sales_mutate_v4','in_store_sales_create_v4','in_store_sales_update_v4','in_store_sales_hold_v4','in_store_sales_prepare_v4','in_store_sales_complete_v4','in_store_sales_cancel_v4','in_store_sales_discard_v4','in_store_sales_takeover_v4','in_store_sales_get_v4','in_store_sales_get_operation_v4','in_store_sales_list_v4','in_store_sales_bootstrap_v4','in_store_sales_list_staff_v4','in_store_sales_recover_staff_v4','in_store_sales_set_staff_v4','in_store_sales_confirm_payment_v4','in_store_sales_revise_payments_v4','in_store_sales_abort_v4','in_store_sales_return_payment_v4','in_store_sales_reconcile_payment_v4','accounting_sales_channel_matches_v4','accounting_pending_receipt_v4','accounting_event_sales_channel_matches_v4','accounting_manual_event_context_v4']) LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,celebix_saas_app,celebix_saas_identity,celebix_saas_workflow,celebix_saas_migrator',fn.oid::regprocedure);
  IF fn.proname LIKE 'in_store_sales_%' AND fn.proname NOT IN('in_store_sales_mutate_v4','in_store_sales_projection_v4') THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO celebix_saas_app',fn.oid::regprocedure);END IF;
 END LOOP;
 UPDATE saas.manual_sales_v4_restore SET after_hash=md5(pg_get_functiondef(signature::regprocedure));
END $seal$;
COMMIT;
